from AlgorithmImports import *
from datetime import datetime, timedelta
from collections import deque


class FiveMinuteSpyCallCrossover(QCAlgorithm):

    def initialize(self) -> None:
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone(TimeZones.NEW_YORK)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(lambda universe: universe.strikes(-50, 50).expiration(0, 365))
        self.option_symbol = option.symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_fill_price = None
        self.no_replacement_today = None

        self.consolidate(self.spy, timedelta(minutes=5), self.on_spy_five_minute_bar)

    def on_data(self, slice: Slice) -> None:
        self.handle_unexpected_spy_position()
        self.handle_expiration_safety()
        self.check_profit_target(slice)
        self.check_expiration_eve_exit()

    def on_spy_five_minute_bar(self, bar: TradeBar) -> None:
        # The built-in period consolidator is aligned to regular-session clock
        # boundaries for minute equity data: 09:30-09:35, 09:35-09:40, etc.
        # It emits only from received minute data and does not forward-fill bars.
        self.fast_closes.append(bar.close)
        self.slow_closes.append(bar.close)

        if len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / len(self.fast_closes)
        slow = sum(self.slow_closes) / len(self.slow_closes)

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        # bar.end_time is the completed five-minute bar's New York end time.
        end_time = bar.end_time.time()
        if end_time < datetime.strptime("09:45", "%H:%M").time():
            return
        if end_time > datetime.strptime("14:30", "%H:%M").time():
            return

        if self.no_replacement_today == self.time.date():
            return

        if self.held_contract is not None or self.has_open_entry_order():
            return

        self.try_enter_from_current_chain()

    def try_enter_from_current_chain(self) -> None:
        chain = self.current_slice.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug(f"{self.time}: Entry skipped: no SPY option chain in Slice.")
            return

        spy_price = self.securities[self.spy].price
        if spy_price <= 0:
            self.debug(f"{self.time}: Entry skipped: invalid SPY price.")
            return

        minimum_expiry_date = self.time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() >= minimum_expiry_date
        ]

        if not calls:
            self.debug(f"{self.time}: Entry skipped: no calls expiring at least 7 calendar days out.")
            return

        nearest_expiry = min(contract.expiry.date() for contract in calls)
        strike_floor = spy_price * 1.01

        candidates = [
            contract for contract in calls
            if contract.expiry.date() == nearest_expiry
            and contract.strike >= strike_floor
        ]

        if not candidates:
            self.debug(
                f"{self.time}: Entry skipped: no {nearest_expiry} call strike "
                f"at least 1% OTM."
            )
            return

        selected = min(candidates, key=lambda c: (c.strike, str(c.symbol)))
        self.entry_ticket = self.market_order(selected.symbol, 1)

        if self.entry_ticket is None or self.entry_ticket.order_id <= 0:
            self.debug(f"{self.time}: Entry skipped: market order submission failed.")
            self.entry_ticket = None
            return

        self.debug(
            f"{self.time}: Entry submitted: {selected.symbol}, "
            f"expiry {selected.expiry.date()}, strike {selected.strike}."
        )

    def check_profit_target(self, slice: Slice) -> None:
        if self.held_contract is None or self.entry_fill_price is None:
            return

        if self.has_open_exit_order():
            return

        quote = slice.quote_bars.get(self.held_contract)
        if quote is None or quote.bid is None or quote.ask is None:
            return

        bid = quote.bid.close
        ask = quote.ask.close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.cancel_other_open_exit_orders()
            quantity = self.portfolio[self.held_contract].quantity
            if quantity > 0:
                self.exit_ticket = self.market_order(self.held_contract, -quantity)
                self.debug(
                    f"{self.time}: Profit-target exit submitted for "
                    f"{self.held_contract}; midpoint {midpoint:.2f}."
                )

    def check_expiration_eve_exit(self) -> None:
        if self.held_contract is None or self.has_open_exit_order():
            return

        expiry_date = self.held_contract.id.date.date()
        previous_trading_day = self.get_previous_trading_day(expiry_date)

        if (
            self.time.date() == previous_trading_day
            and self.time.hour == 15
            and self.time.minute == 45
        ):
            quantity = self.portfolio[self.held_contract].quantity
            if quantity > 0:
                self.cancel_other_open_exit_orders()
                self.exit_ticket = self.market_order(self.held_contract, -quantity)
                self.debug(
                    f"{self.time}: Expiration-eve exit submitted for "
                    f"{self.held_contract}."
                )

    def handle_expiration_safety(self) -> None:
        if self.held_contract is None:
            return

        expiry_date = self.held_contract.id.date.date()
        if self.time.date() < expiry_date:
            return

        self.no_replacement_today = self.time.date()

        if not self.has_open_exit_order():
            quantity = self.portfolio[self.held_contract].quantity
            if quantity > 0:
                self.cancel_other_open_exit_orders()
                self.exit_ticket = self.market_order(self.held_contract, -quantity)
                self.debug(
                    f"{self.time}: Expiration safety liquidation submitted for "
                    f"{self.held_contract}."
                )

    def handle_unexpected_spy_position(self) -> None:
        quantity = self.portfolio[self.spy].quantity
        if quantity == 0:
            return

        self.no_replacement_today = self.time.date()
        if not self.has_open_order_for_symbol(self.spy):
            self.market_order(self.spy, -quantity)
            self.debug(
                f"{self.time}: Unexpected SPY position ({quantity}) from "
                f"exercise/assignment; liquidation submitted."
            )

    def on_order_event(self, order_event: OrderEvent) -> None:
        if order_event.status not in [OrderStatus.FILLED, OrderStatus.PARTIALLY_FILLED]:
            return

        if self.entry_ticket is not None and order_event.order_id == self.entry_ticket.order_id:
            if order_event.fill_quantity > 0:
                self.held_contract = order_event.symbol
                self.entry_fill_price = order_event.fill_price
                self.debug(
                    f"{self.time}: Entry filled: {order_event.symbol} at "
                    f"{order_event.fill_price:.2f}."
                )

            if order_event.status == OrderStatus.FILLED:
                self.entry_ticket = None
            return

        if self.exit_ticket is not None and order_event.order_id == self.exit_ticket.order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(
                    f"{self.time}: Exit filled: {order_event.symbol} at "
                    f"{order_event.fill_price:.2f}."
                )
                self.exit_ticket = None
                self.held_contract = None
                self.entry_fill_price = None

    def on_assignment_order_event(self, assignment_event: OrderEvent) -> None:
        self.no_replacement_today = self.time.date()
        self.debug(
            f"{self.time}: Unexpected option assignment event for "
            f"{assignment_event.symbol}; SPY exposure will be liquidated."
        )

    def has_open_entry_order(self) -> bool:
        return (
            self.entry_ticket is not None
            and self.entry_ticket.status not in [
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ]
        )

    def has_open_exit_order(self) -> bool:
        return (
            self.exit_ticket is not None
            and self.exit_ticket.status not in [
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ]
        )

    def has_open_order_for_symbol(self, symbol: Symbol) -> bool:
        return any(
            order.symbol == symbol
            for order in self.transactions.get_open_orders(symbol)
        )

    def cancel_other_open_exit_orders(self) -> None:
        if self.held_contract is None:
            return

        for order in self.transactions.get_open_orders(self.held_contract):
            if self.exit_ticket is None or order.id != self.exit_ticket.order_id:
                self.transactions.cancel_order(order.id)

    def get_previous_trading_day(self, date) -> object:
        candidate = date - timedelta(days=1)
        exchange_hours = self.securities[self.spy].exchange.hours

        while not exchange_hours.is_date_open(candidate, False):
            candidate -= timedelta(days=1)

        return candidate
