from AlgorithmImports import *


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone(TimeZones.NEW_YORK)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-100, 100)
            .expiration(0, 365)
        )
        self.option_symbol = option.symbol

        self.fast_closes = RollingWindow[float](5)
        self.slow_closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bucket_date = None
        self.bucket_minutes = {}

        self.held_option = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.expiration_date = None
        self.no_entry_dates = set()
        self.equity_exit_order_id = None

        self.schedule.on(
            self.date_rules.every_day(self.spy),
            self.time_rules.at(15, 45),
            self._scheduled_expiration_exit
        )

    def on_data(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_safety_exit()

        spy_bar = data.bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_consolidation(spy_bar, data)

        self._check_profit_target(data)

    def _update_five_minute_consolidation(self, bar: TradeBar, data: Slice):
        end = bar.end_time
        local_date = end.date()

        if self.minute_bucket_date != local_date:
            self.minute_bucket_date = local_date
            self.bucket_minutes = {}

        # Minute bars ending from 09:31 through 16:00 form regular-session bars.
        if end.time() <= time(9, 30) or end.time() > time(16, 0):
            return

        minutes_after_midnight = end.hour * 60 + end.minute
        bucket_end_minutes = ((minutes_after_midnight + 4) // 5) * 5
        bucket_end = datetime.combine(
            local_date,
            time(bucket_end_minutes // 60, bucket_end_minutes % 60)
        )

        if bucket_end.time() < time(9, 35) or bucket_end.time() > time(16, 0):
            return

        if bucket_end not in self.bucket_minutes:
            self.bucket_minutes[bucket_end] = {}

        self.bucket_minutes[bucket_end][end] = bar

        # A valid five-minute bar must contain all five actual minute bars.
        if end != bucket_end:
            return

        bucket = self.bucket_minutes.pop(bucket_end)
        expected_times = [
            bucket_end - timedelta(minutes=offset)
            for offset in range(0, 5)
        ]

        if any(expected not in bucket for expected in expected_times):
            return

        # The close of the final minute is the five-minute bar close.
        self._on_five_minute_bar(bucket_end, bar.close, data)

    def _on_five_minute_bar(self, bar_end: datetime, close: float, data: Slice):
        self.fast_closes.add(float(close))
        self.slow_closes.add(float(close))

        if not self.fast_closes.is_ready or not self.slow_closes.is_ready:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        self._try_enter_call(data)

    def _try_enter_call(self, data: Slice):
        today = self.time.date()

        if today in self.no_entry_dates:
            return

        if self.held_option is not None or self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Entry skipped: no current SPY option chain.")
            return

        underlying_bar = data.bars.get(self.spy)
        underlying_price = (
            float(underlying_bar.close)
            if underlying_bar is not None
            else float(self.securities[self.spy].price)
        )

        if underlying_price <= 0:
            self.debug("Entry skipped: invalid SPY price.")
            return

        eligible_expiries = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.expiry.date() >= today + timedelta(days=7)
        })

        if not eligible_expiries:
            self.debug("Entry skipped: no expiration at least seven calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = underlying_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == selected_expiry
            and float(contract.strike) >= minimum_strike
        ]

        if not candidates:
            self.debug(
                f"Entry skipped: no call at least 1% OTM for expiry {selected_expiry}."
            )
            return

        contract = min(
            candidates,
