        if self.held_option is not None and self.Time.Date >= self.held_option.ID.Date:
            self.no_entry_date = self.Time.Date
            if self.Portfolio[self.held_option].Quantity != 0 and not self._has_open_exit_order():
                self.Debug(f"Expiration safety exit: {self.held_option}")
                self._submit_exit("expiration safety")
            return

        self._evaluate_option_exits(data)
        self._update_five_minute_builder(data)

    def _update_five_minute_builder(self, data):
        if self.spy not in data.Bars:
            return

        minute_bar = data.Bars[self.spy]
        end_time = minute_bar.EndTime
        minute_of_day = end_time.Hour * 60 + end_time.Minute

        # Regular-session minute bars ending 09:31 through 16:00 ET.
        if minute_of_day < 571 or minute_of_day > 960:
            return

        bucket_number = (minute_of_day - 571) // 5
        bucket_key = (end_time.Year, end_time.DayOfYear, bucket_number)

        if self.minute_bucket_key != bucket_key:
            self.minute_bucket_key = bucket_key
            self.minute_bucket_bars = []

        self.minute_bucket_bars.append(minute_bar)

        expected_end_minute = 575 + bucket_number * 5
        if minute_of_day != expected_end_minute:
            return

        expected_minutes = list(range(expected_end_minute - 4, expected_end_minute + 1))
        actual_minutes = [
            bar.EndTime.Hour * 60 + bar.EndTime.Minute
            for bar in self.minute_bucket_bars
        ]

        # A missing minute means this five-minute interval is discarded.
        if actual_minutes == expected_minutes:
            self._on_five_minute_bar(
                end_time,
                float(self.minute_bucket_bars[-1].Close),
                data
            )

        self.minute_bucket_bars = []

    def _on_five_minute_bar(self, end_time, close, data):
        self.five_minute_closes.append(close)
        if len(self.five_minute_closes) > 20:
            self.five_minute_closes.pop(0)

        if len(self.five_minute_closes) < 20:
            return

        fast = sum(self.five_minute_closes[-5:]) / 5.0
        slow = sum(self.five_minute_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        minute_of_day = end_time.Hour * 60 + end_time.Minute
        if minute_of_day < 585 or minute_of_day > 870:  # 09:45 through 14:30
            return

        self._try_enter_call(data, close)

    def _try_enter_call(self, data, spy_price):
        if self.no_entry_date == self.Time.Date:
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Quantity != 0:
            return

        if self.entry_order_id is not None or self._has_open_exit_order():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        minimum_expiry = self.Time.Date.AddDays(7)
        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.Date >= minimum_expiry
        ]

        if not eligible:
            self.Debug("Skipped entry: no call expiration at least seven calendar days away.")
            return

        selected_expiry = min(contract.Expiry.Date for contract in eligible)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in eligible
            if contract.Expiry.Date == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no call strike >= 101% of SPY price ({spy_price:.2f})."
            )
            return

        selected = min(candidates, key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        self.held_option = selected.Symbol
        self.entry_order_id = ticket.OrderId
        self.entry_fill_price = None
        self.time_stop_date = None

        self.Debug(
            f"Entry submitted: {selected.Symbol}, strike {selected.Strike}, "
            f"expiry {selected.Expiry.Date}"
        )

    def _evaluate_option_exits(self, data):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if (
            self.time_stop_date is not None
            and self.Time.Date == self.time_stop_date
            and self.Time.Hour == 15
            and self.Time.Minute == 45
            and not self._has_open_exit_order()
        ):
            self._submit_exit("15:45 pre-expiration time stop")
            return

        if self.entry_fill_price is None or self._has_open_exit_order():
            return

        quote = data.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self._submit_exit(
                f"50% profit target (midpoint {midpoint:.2f}, entry {self.entry_fill_price:.2f})"
            )

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id, "Replacing with market exit")

        ticket = self.MarketOrder(self.held_option, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {self.held_option}; {reason}")

    def _has_open_exit_order(self):
        if self.held_option is None:
            return False

        return any(
            order.Symbol == self.held_option
            for order in self.Transactions.GetOpenOrders()
        )

    def _flatten_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0:
            return

        if self.spy_flatten_order_id is None:
            ticket = self.MarketOrder(self.spy, -spy_quantity)
            self.spy_flatten_order_id = ticket.OrderId
            self.Debug(
                f"Unexpected SPY exercise/assignment position detected; "
                f"liquidating {spy_quantity} shares."
            )

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order_id = None

                if self.held_option is not None:
                    expiry = self.held_option.ID.Date
                    self.time_stop_date = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(expiry)

                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {self.entry_fill_price:.2f}"
                )

            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order did not fill: {order_event.Symbol}")
                self.entry_order_id = None
                if self.held_option is not None and self.Portfolio[self.held_option].Quantity == 0:
                    self.held_option = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {float(order_event.FillPrice):.2f}"
                )
                self.exit_order_id = None
                self.held_option = None
                self.entry_fill_price = None
                self.time_stop_date = None

            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.spy_flatten_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.spy_flatten_order_id = None
