                data
            )

        self.minute_bucket_bars = []

    def _on_five_minute_bar(self, end_time, close, data):
        self.five_minute_closes.append(close)
        if len(self.five_minute_closes) > 20:
            self.five_minute_closes.pop(0)

        if len(self.five_minute_closes) < 20:
            return

        fast = sum(self.five_minute_closes[-5:]) / 5.0
        slow = sum(self.five_minute_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        minute_of_day = end_time.Hour * 60 + end_time.Minute
        if minute_of_day < 585 or minute_of_day > 870:  # 09:45 through 14:30
            return

        self._try_enter_call(data, close)

