        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-200, 200, timedelta(days=0), timedelta(days=730))
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=20)
        self.pending_entry_bar_end = None

        self.held_contract = None
        self.contract_expiry_date = None
        self.entry_fill_price = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.spy_cleanup_order_id = None
        self.expiration_entry_block_date = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # A missing minute bar produces no consolidated bar, so no values are filled forward.
        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

            self.closes.append(bar.Close)

            current_fast = sum(list(self.closes)[-5:]) / 5.0
            current_slow = sum(self.closes) / 20.0

            end_time = bar.EndTime.time()
            eligible_time = time(9, 45) <= end_time <= time(14, 30)

            if (eligible_time
                    and previous_fast <= previous_slow
                    and current_fast > current_slow):
                self.pending_entry_bar_end = bar.EndTime
        else:
            self.closes.append(bar.Close)

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        # Never retain an expiring option position into its expiration date.
        if self.IsOptionInvested() and self.Time.date() >= self.contract_expiry_date:
            self.expiration_entry_block_date = self.Time.date()
            self.SubmitExit("expiration processing")
            return

        if self.IsOptionInvested():
            self.EvaluateExit(slice)

        if self.pending_entry_bar_end is not None:
            signal_time = self.pending_entry_bar_end
            self.pending_entry_bar_end = None

            # The signal is acted upon once, in the Slice corresponding to its close.
            if self.Time != signal_time:
                return

            if self.expiration_entry_block_date == self.Time.date():
                self.Debug("Skipped entry: expiration processing blocked entries today.")
                return

            if self.IsOptionInvested() or self.IsEntryOrderOpen():
                self.Debug("Skipped entry: option position or entry order already exists.")
                return

            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: no current SPY TradeBar.")
            return

        spy_price = slice.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = [
            contract for contract in slice.OptionChains[self.option_symbol]
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug("Skipped entry: no calls with at least 7 calendar days to expiry.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying 1% OTM call at nearest expiry.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.contract_expiry_date = selected.Expiry.date()
        self.entry_fill_price = None

        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}"
        )

    def EvaluateExit(self, slice):
        if self.IsExitOrderOpen():
            return

        # Scheduled time stop is independent of quote availability.
        if (self.Time.date() == self.PreviousTradingDay(self.contract_expiry_date)
                and self.Time.time() == time(15, 45)):
            self.SubmitExit("15:45 pre-expiration time stop")
            return

        if self.entry_fill_price is None or self.option_symbol not in slice.OptionChains:
            return

        held_contract = None
        for contract in slice.OptionChains[self.option_symbol]:
            if contract.Symbol == self.held_contract:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit(
                f"50% profit target, midpoint {midpoint:.2f}, entry {self.entry_fill_price:.2f}"
            )

    def SubmitExit(self, reason):
        if not self.IsOptionInvested() or self.IsExitOrderOpen():
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Id != self.exit_order_id:
                self.Transactions.CancelOrder(order.Id, "Canceling other exit order")

        quantity = -self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {self.held_contract}; {reason}.")

    def HandleUnexpectedSpyPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if self.spy_cleanup_order_id is not None:
            order = self.Transactions.GetOrderById(self.spy_cleanup_order_id)
            if order is not None and order.Status not in (
                OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
            ):
                return

        quantity = -self.Portfolio[self.spy].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self.spy, quantity)
            self.spy_cleanup_order_id = ticket.OrderId
            self.Debug("Unexpected SPY exercise/assignment position detected; liquidating SPY.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry order {order_event.OrderId} did not fill.")
                self.entry_order_id = None
                if not self.IsOptionInvested():
                    self.ClearOptionState()

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                self.exit_order_id = None
                if not self.IsOptionInvested():
                    self.ClearOptionState()
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

    def IsOptionInvested(self):
        return self.held_contract is not None and self.Portfolio[self.held_contract].Invested

    def IsEntryOrderOpen(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status not in (
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        )

    def IsExitOrderOpen(self):
        if self.exit_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.exit_order_id)
        return order is not None and order.Status not in (
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        )

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(datetime.combine(candidate, time.min), False):
            candidate -= timedelta(days=1)

        return candidate

    def ClearOptionState(self):
        self.held_contract = None
        self.contract_expiry_date = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
