                f"{selected_expiry}."
            )
            return

        contract = min(candidates, key=lambda x: (float(x.Strike), str(x.Symbol)))
        ticket = self.MarketOrder(contract.Symbol, 1)

        if ticket.OrderId > 0:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"{self.Time}: Entry submitted: {contract.Symbol}, "
                f"expiry {contract.Expiry.date()}, strike {contract.Strike}."
            )
        else:
            self.Debug(f"{self.Time}: Entry skipped; market order was not accepted.")

    def _process_minute_exit(self, data: Slice):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self._is_pre_expiry_time_stop():
            self._submit_exit("pre-expiration time stop")
            return

        if self.entry_fill_price is None or self._exit_order_is_open():
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self._submit_exit("50% profit target")

    def _is_pre_expiry_time_stop(self) -> bool:
        if self.held_expiry is None:
            return False

        prior_trading_day = self.held_expiry.date() - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(prior_trading_day, time.min), False
        ):
            prior_trading_day -= timedelta(days=1)

        return (
            self.Time.date() == prior_trading_day
            and self.Time.time() >= time(15, 45)
        )

    def _submit_exit(self, reason: str):
        if self.held_contract is None or self._exit_order_is_open():
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id, f"Replacing exit: {reason}")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket.OrderId > 0:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"{self.Time}: Exit submitted for {self.held_contract}: {reason}.")

    def _entry_order_is_open(self) -> bool:
        if self.entry_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _exit_order_is_open(self) -> bool:
        if self.exit_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0:
            return

        has_open_spy_order = any(
            order.Symbol == self.spy
            for order in self.Transactions.GetOpenOrders(self.spy)
        )

        if not has_open_spy_order:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position from exercise/assignment; "
                f"liquidating {spy_quantity} shares."
            )
            self.MarketOrder(self.spy, -spy_quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled for {self.held_contract} at "
                    f"{self.entry_fill_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None
                self.Debug(f"{self.Time}: Entry order did not complete.")

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled for {order_event.Symbol} at "
                    f"{float(order_event.FillPrice):.2f}."
                )
                self.exit_order_id = None
                self.held_contract = None
                self.held_expiry = None
                self.entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

