        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.SetSecurityInitializer(
            BrokerageModelSecurityInitializer(
                self.BrokerageModel,
                FuncSecuritySeeder(self.GetLastKnownPrices)
            )
        )
        self.OptionChainProvider  # Retain normal LEAN option-chain support.
        self.SetOptionFilter()

        self.five_minute_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_end = None
        self.bucket_closes = {}

        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_liquidation_order_id = None
        self.no_entry_date = None

    def SetOptionFilter(self):
        option = self.Securities[self.option_symbol]
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_safety()
        self._evaluate_option_exit(data)

        if self.spy in data.Bars:
            self._update_five_minute_builder(data.Bars[self.spy], data)

    def _update_five_minute_builder(self, minute_bar: TradeBar, data: Slice):
        bar_end = minute_bar.EndTime
        session_open = datetime.combine(bar_end.date(), time(9, 30))
        session_close = datetime.combine(bar_end.date(), time(16, 0))

        # Minute bars are identified by their EndTime. Regular-session bars ending
        # 09:31 through 16:00 are assigned to NY-clock-aligned five-minute buckets.
        if bar_end <= session_open or bar_end > session_close:
            return

        minutes_from_open = int((bar_end - session_open).total_seconds() / 60)
        bucket_number = (minutes_from_open + 4) // 5
        bucket_end = session_open + timedelta(minutes=5 * bucket_number)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.bucket_closes = {}

        self.bucket_closes[bar_end] = minute_bar.Close

        if bar_end != bucket_end:
            return

        expected_times = {
            bucket_end - timedelta(minutes=i)
            for i in range(5)
        }

        # A missing constituent minute means this five-minute bar is missing.
        if set(self.bucket_closes.keys()) != expected_times:
            return

        self._on_completed_five_minute_bar(
            self.bucket_closes[bucket_end],
            bucket_end,
            data
        )

    def _on_completed_five_minute_bar(
        self,
        close: float,
        bar_end: datetime,
        data: Slice
    ):
        self.five_minute_closes.append(close)

        if len(self.five_minute_closes) < 20:
            return

        closes = list(self.five_minute_closes)
        fast = sum(closes[-5:]) / 5.0
        slow = sum(closes) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        if bullish_crossover and eligible_time:
            self._try_enter_call(data)

    def _try_enter_call(self, data: Slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None or self._has_option_holding():
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped call selection: SPY has no valid current price.")
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Skipped call selection: no current SPY option chain.")
            return

        chain = data.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Skipped call selection: no call expiry at least 7 calendar days out.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped call selection: no >=1% OTM call for {selected_expiry}."
            )
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.entry_price = None

        self.Debug(
            f"Entry submitted: {selected.Symbol} exp {selected_expiry}, "
            f"strike {selected.Strike}."
        )

    def _evaluate_option_exit(self, data: Slice):
        if self.held_contract is None:
            return

        if not self.Portfolio[self.held_contract].Invested:
            return

        if self.exit_order_id is not None:
            return

        # Profit target requires a current, strictly positive bid and ask.
        if self.entry_price is not None and self.held_contract in data.QuoteBars:
            quote = data.QuoteBars[self.held_contract]
            bid = quote.Bid.Close if quote.Bid is not None else 0
            ask = quote.Ask.Close if quote.Ask is not None else 0

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self.entry_price * 1.50:
                    self._submit_option_exit("50% profit target")
                    return

        expiry_date = self.held_contract.ID.Date.date()
        if (
            self.Time.date() == self._previous_spy_trading_day(expiry_date)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_option_exit("15:45 pre-expiration time stop")

    def _handle_expiration_safety(self):
        if self.held_contract is None:
            return

        if not self.Portfolio[self.held_contract].Invested:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            if self.exit_order_id is None:
                self._submit_option_exit("expiration safety liquidation")

    def _submit_option_exit(self, reason: str):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        # This strategy never intentionally maintains more than one exit order.
        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0 or self.equity_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -spy_quantity)
        self.equity_liquidation_order_id = ticket.OrderId
        self.Debug(
            f"Unexpected SPY position ({spy_quantity}) from exercise/assignment; "
            "submitted immediate liquidation."
        )

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _has_option_holding(self):
        for security in self.Securities.Values:
            if (
                security.Type == SecurityType.Option
                and self.Portfolio[security.Symbol].Invested
            ):
                return True
        return False

    def OnOrderEvent(self, order_event: OrderEvent):
        terminal = (
            order_event.Status == OrderStatus.Filled
            or order_event.Status == OrderStatus.Canceled
            or order_event.Status == OrderStatus.Invalid
        )

        if order_event.OrderId == self.entry_order_id:
            if order_event.FillQuantity > 0:
                self.entry_price = order_event.FillPrice
                self.held_contract = order_event.Symbol
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}."
                )

            if terminal:
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if terminal:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}."
                    )
                self.exit_order_id = None

                if (
                    self.held_contract == order_event.Symbol
                    and not self.Portfolio[order_event.Symbol].Invested
                ):
                    self.held_contract = None
                    self.entry_price = None

        if order_event.OrderId == self.equity_liquidation_order_id and terminal:
            self.equity_liquidation_order_id = None
